import type { z } from "zod";
import { srdMonsters } from "@/engine/srd/library";
import type { RulesetInput, TableResult } from "@/engine/ruleset/ruleset";
import data from "./utterdark-data.json";

// The Utterdark content that comes from the DM's spreadsheets: items and
// augments, crafting recipes, races, roll tables and encounter tables.
// utterdark-data.json is generated by scripts/import-utterdark-sheets.py.

type Input<K extends "items" | "recipes" | "races" | "rollTables"> = NonNullable<RulesetInput[K]>[number];
type Result = z.input<typeof TableResult>;
type Band = { min: number; max: number | null; text: string; results: Result[] };

function slug(s: string) {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}

export const SHEET_ITEMS = data.items as Input<"items">[];
export const SHEET_RECIPES = data.recipes as Input<"recipes">[];
export const SHEET_RACES = data.races as Input<"races">[];

/** Some names on the sheets differ from the SRD 5.2 names of the same creature. */
const SRD_NAMES: Record<string, string> = {
  goblin: "Goblin Warrior",
  goblins: "Goblin Warrior",
  bugbear: "Bugbear Warrior",
  bugbears: "Bugbear Warrior",
  hobgoblin: "Hobgoblin Warrior",
  kobold: "Kobold Warrior",
};

function srdName(name: string): string | null {
  const clean = name.replace(/^an? /i, "").replace(/[.]$/, "").trim();
  const all = srdMonsters();
  const candidates = [clean, clean.replace(/s$/, ""), clean.replace(/es$/, ""), SRD_NAMES[clean.toLowerCase()] ?? ""];
  for (const c of candidates) {
    const hit = all.find((m) => m.name.toLowerCase() === c.toLowerCase());
    if (hit) return hit.name;
  }
  return null;
}

/** "1 Ettercap and 1d4-1 Giant Spiders or Giant Centipedes" → spawn the Ettercap; the choice is left to the DM. */
function spawnResults(monsters: string, used: Set<string>): { results: Result[]; byHand: boolean } {
  const results: Result[] = [];
  let byHand = false;
  for (const raw of monsters.split(/ and | amd | \+ (?=\d)/i)) {
    const part = raw.trim().replace(/\s+-\s*1$/, "");
    if (!part || / or |,/.test(part)) {
      byHand = true;
      continue;
    }
    const m = /^(\d+(?:d\d+)?(?:\s*[+-]\s*\d+)?)\s+(.+)$/.exec(part);
    const name = m ? srdName(m[2]) : null;
    if (!m || !name) {
      byHand = true;
      continue;
    }
    used.add(name);
    results.push({ type: "spawnMonster", creatureId: slug(name), count: m[1].replace(/\s+/g, "") });
  }
  return { results, byHand };
}

const ENCOUNTER_LINKS: Record<string, string> = {
  "Hidden monster": "encounter-inconvenience",
  "Overt monster (Low Threat)": "encounter-low",
  "Overt monster (Medium Threat)": "encounter-medium",
  "Overt monster (High Threat)": "encounter-high",
};

/** Monsters the encounter tables can spawn, so they're in the monster library. */
export const ENCOUNTER_MONSTERS = new Set<string>();

export const ENCOUNTER_TABLES: Input<"rollTables">[] = Object.entries(data.encounters).map(([id, t]) => ({
  id,
  name: t.name === "Encounter Table" ? "Encounter" : `Encounter: ${t.name}`,
  category: "encounter",
  die: t.die || "1d20",
  modifierNote: id === "encounter" ? "Roll when units enter a new region, along with the New Region table." : "",
  bands: t.bands.map((b): Band => {
    const link = ENCOUNTER_LINKS[b.text];
    if (id === "encounter") {
      return {
        min: b.min,
        max: b.max,
        text: link === "encounter-inconvenience" ? "A hidden monster: place what this rolls as hidden." : b.text,
        results: link ? [{ type: "rollTable", tableId: link }] : [],
      };
    }
    const spawn = spawnResults(b.monsters, ENCOUNTER_MONSTERS);
    return { min: b.min, max: b.max, text: spawn.byHand ? `${b.text} (place what isn't SRD, or the choice, by hand)` : b.text, results: spawn.results };
  }),
}));

const DEFICITS: Record<string, { resourceId: string; perUnit: number }> = {
  "deficit-gold": { resourceId: "gold", perUnit: 1 },
  "deficit-food": { resourceId: "food", perUnit: 2 },
};

export const SHEET_TABLES: Input<"rollTables">[] = data.rollTables.map((t) => ({
  ...(t as Input<"rollTables">),
  buildingBonus: t.id === "hunters-post" ? { buildingId: "hunters-post", perTier: 1 } : null,
  deficitResourceId: DEFICITS[t.id]?.resourceId ?? null,
  deficitPerUnit: DEFICITS[t.id]?.perUnit ?? 0,
  perRegionsBonus: t.id === "turn-event" ? 6 : null,
}));

/** Materials each monster can be harvested for, by SRD name. */
export function harvestFor(srdMonsterName: string): { itemId: string; qty: number }[] {
  const ids = (data.harvest as Record<string, string[]>)[srdMonsterName] ?? [];
  return ids.map((itemId) => ({ itemId, qty: 1 }));
}

/** Spells that scrolls cast; the preset makes sure they exist. */
export const SCROLL_SPELLS: string[] = data.scrollSpells;
